import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static final long LIM = Long.MAX_VALUE - MOD * MOD;
    static int[][][] mat = new int[60][32][32];
    static int[][] have = new int[32][32];
    static int[][] tmp = new int[32][32];

    static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    static void multiply(int[][] A, int[][] B, int[][] C, int size) {
        for (int i = 0; i <= size; ++i) {
            for (int j = 0; j <= size; ++j) {
                long sum = 0;
                for (int k = 0; k <= size; ++k) {
                    if (sum > LIM) sum %= MOD;
                    sum += (long) A[i][k] * B[k][j];
                }
                C[i][j] = (int) (sum % MOD);
            }
        }
    }

    static void copyMatrix(int[][] A, int[][] B, int size) {
        for (int i = 0; i <= size; ++i) {
            for (int j = 0; j <= size; ++j) {
                B[i][j] = A[i][j];
            }
        }
    }

    public static void run() {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int base = sc.nextInt();
        int size = base;

        // Initialize mat[0][i]
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j <= size; ++j) {
                for (int k = 0; k <= size; ++k) {
                    mat[0][i][j] = (i == j || j == k) ? 1 : 0;
                }
            }
        }

        int ci = 0, cj = 0;
        long step = 1;
        while (step <= n / size) {
            ++ci;
            step *= size;
        }

        for (int i = 1; i <= ci; ++i) {
            for (int j = 0; j < size; ++j) {
                for (int k = 0; k <= size; ++k) {
                    for (int l = 0; l <= size; ++l) {
                        mat[i][j][k] = (k == l) ? 1 : 0;
                    }
                }
                for (int k = 0; k < size; ++k) {
                    multiply(mat[i][j], mat[i - 1][(j + k) % size], tmp, size);
                    copyMatrix(tmp, mat[i][j], size);
                }
            }
        }

        for (int k = 0; k <= size; ++k) {
            for (int l = 0; l <= size; ++l) {
                have[k][l] = (k == l) ? 1 : 0;
            }
        }

        for (; ci >= 0; --ci, step /= size) {
            int times = (int) ((n / step) % size);
            for (int x = 0; x < times; ++x) {
                multiply(have, mat[ci][cj], tmp, size);
                copyMatrix(tmp, have, size);
                ++cj;
                if (cj >= size) cj -= size;
            }
        }

        int result = 0;
        for (int k = 0; k <= size; ++k) {
            result += have[k][size];
            if (result >= MOD) result -= MOD;
        }
        System.out.println(result);
        sc.close();
    }

    public static void main(String[] args) {
        run();
    }
}

